import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Hosts","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/hosts.md","filePath":"ecosystem/hosts.md"}`),a={name:`ecosystem/hosts.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="hosts" tabindex="-1">Hosts <a class="header-anchor" href="#hosts" aria-label="Permalink to “Hosts”">​</a></h1><p>Hosts are the distribution layer — the programs that embed the Handl platform and expose it to users. The platform itself is a Cargo workspace plus <code>.hnl</code> packages; a host decides which engines fill the operation slots and which extensions are loaded.</p><h2 id="public-hosts" tabindex="-1">Public hosts <a class="header-anchor" href="#public-hosts" aria-label="Permalink to “Public hosts”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it is</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/host" target="_blank" rel="noreferrer">host</a></td><td>The reference Rust platform — runtime, loaders, <code>plugin-lib-*</code>/<code>plugin-ext-*</code> internals, and <code>plugin-lib-stdlib</code>, the library-as-data registry</td></tr><tr><td><a href="https://github.com/handl-lang/host-cli" target="_blank" rel="noreferrer">host-cli</a></td><td>The <code>hnl</code> CLI — a <em>dumb host</em> that links exactly one sibling engine set and dispatches to the <code>ext-*</code> dynamic extensions</td></tr></tbody></table><p>The <code>hnl</code> binary is deliberately thin: <code>hnl run</code>, <code>hnl eval</code>, <code>hnl fmt</code>, <code>hnl lint</code>, <code>hnl typecheck</code>, <code>hnl test</code>, <code>hnl compile</code>, <code>hnl codegen</code>, <code>hnl transform</code>, <code>hnl plugin</code>, <code>hnl kit</code>, <code>hnl codemod</code> are each a separate <code>ext-*</code> shared library discovered via <code>HANDL_EXT_DIR</code> / <code>~/.handl/ext</code> — see <a href="/docs/ecosystem/extensions.html">Extensions</a>. This keeps the core small and lets deployments ship only the operations they need.</p><p>Additional hosts exist for editor and language-server surfaces; they are part of the private platform layer.</p>`,6)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};